program.source:
Funcion palabra <- ComoLeFue(codigo Como Entero)
  Definir palabra Como Cadena;
  Si codigo = 200 Entonces
    palabra <- "bien";
  Sino
    palabra <- "problema";
  FinSi
FinFuncion

Algoritmo Estado
  Definir codigo Como Entero;
  Leer codigo;
  Escribir ComoLeFue(codigo);
FinAlgoritmo

